CREATE TABLE IF NOT EXISTS support_businesses (id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, name text NOT NULL, currency text NOT NULL, policy jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS support_customers (id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES support_businesses(id), name text NOT NULL, email text NOT NULL, plan text NOT NULL, session_token text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS support_payments (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES support_customers(id), amount_cents integer NOT NULL CHECK(amount_cents>0), currency text NOT NULL, merchant_ref text NOT NULL, description text NOT NULL, status text NOT NULL CHECK(status IN ('captured','refunded')), created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS support_cases (id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES support_businesses(id), customer_id uuid NOT NULL REFERENCES support_customers(id), status text NOT NULL CHECK(status IN ('open','awaiting_approval','escalated','resolved')), priority text NOT NULL CHECK(priority IN ('P1','P2','P3')), intent text, analysis jsonb, ownership text NOT NULL DEFAULT 'bot' CHECK(ownership IN ('bot','staff')), ownership_version integer NOT NULL DEFAULT 0, assigned_to text, active_run_id uuid, active_run_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_messages (id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES support_cases(id), role text NOT NULL CHECK(role IN ('customer','assistant','operator','system')), body text NOT NULL CHECK(length(trim(body))>0), source_refs jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_proposals (id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES support_cases(id), tool text NOT NULL, args jsonb NOT NULL, args_hash text NOT NULL, risk text NOT NULL CHECK(risk IN ('low','high')), status text NOT NULL CHECK(status IN ('pending','approved','executing','executed','rejected','failed','denied','unknown')), policy jsonb NOT NULL, decided_by text, decided_at timestamptz, result jsonb, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_payment_executions (payment_id uuid PRIMARY KEY REFERENCES support_payments(id), proposal_id uuid NOT NULL UNIQUE REFERENCES support_proposals(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_refunds (id uuid PRIMARY KEY, payment_id uuid NOT NULL UNIQUE REFERENCES support_payments(id), proposal_id uuid NOT NULL UNIQUE REFERENCES support_proposals(id), amount_cents integer NOT NULL CHECK(amount_cents>0), provider_ref text NOT NULL, simulated boolean NOT NULL DEFAULT true CHECK(simulated), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_audit_events (id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES support_cases(id), type text NOT NULL, actor text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_agent_runs (id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES support_cases(id), provider text NOT NULL, model text NOT NULL, status text NOT NULL CHECK(status IN ('ok','failed','fallback')), steps integer NOT NULL, tool_calls jsonb NOT NULL, latency_ms integer NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_knowledge (id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES support_businesses(id), title text NOT NULL, category text NOT NULL, content text NOT NULL, version integer NOT NULL CHECK(version>0), status text NOT NULL CHECK(status IN ('draft','published','revoked')), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_skills (id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES support_businesses(id), name text NOT NULL, content text NOT NULL, revision integer NOT NULL CHECK(revision>0), enabled boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_settings (business_id uuid PRIMARY KEY REFERENCES support_businesses(id), version integer NOT NULL, language text NOT NULL, tone text NOT NULL, require_approval boolean NOT NULL CHECK(require_approval), refund_limit_cents integer NOT NULL CHECK(refund_limit_cents>0), duplicate_window_minutes integer NOT NULL CHECK(duplicate_window_minutes>0), enabled_tools jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS support_cases_queue ON support_cases(priority,updated_at DESC);
CREATE INDEX IF NOT EXISTS support_messages_case ON support_messages(case_id,created_at);
CREATE INDEX IF NOT EXISTS support_proposals_case ON support_proposals(case_id);
ALTER TABLE support_messages ADD COLUMN IF NOT EXISTS source_refs jsonb NOT NULL DEFAULT '[]';
